package android.util; public class SparseIntArray {private final java.util.TreeMap<Integer,Integer> data=new java.util.TreeMap<>();public void put(int k,int v){data.put(k,v);}public int size(){return data.size();}public int keyAt(int i){return (int)data.keySet().toArray()[i];}public int valueAt(int i){return data.get(keyAt(i));}}